import{b as e,O as a,g as s,j as i}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"安装与启动","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/install/index.md","filePath":"性能测试/1.Jmeter/02.安装与启动.md","lastUpdated":1781755252000}'),r={name:"performance/jmeter/install/index.md"};function l(o,t,n,d,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h1><blockquote><p>装好 JMeter，认识界面布局，做好动手前的准备。</p></blockquote><h2 id="一条命令搞定-macos" tabindex="-1">一条命令搞定（macOS） <a class="header-anchor" href="#一条命令搞定-macos" aria-label="Permalink to &quot;一条命令搞定（macOS）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jmeter</span></span></code></pre></div><p>安装完成后启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span></span></code></pre></div><p>等几秒钟，JMeter 的 GUI 窗口就会出现。</p><blockquote><p>当前 brew 默认安装的是 <strong>JMeter 5.6.x</strong>，本教程所有操作均基于此版本。后续若有 6.x 大版本更新，界面和菜单路径可能有差异，届时注意对照。</p></blockquote><h2 id="通用安装方式" tabindex="-1">通用安装方式 <a class="header-anchor" href="#通用安装方式" aria-label="Permalink to &quot;通用安装方式&quot;">​</a></h2><p>如果不用 macOS，或者想手动安装：</p><ol><li>打开 <a href="https://jmeter.apache.org/download_jmeter.cgi" target="_blank" rel="noreferrer">jmeter.apache.org/download_jmeter.cgi</a></li><li>下载 <code>Binaries</code> 下的 <code>.zip</code> 或 <code>.tgz</code> 包</li><li>解压到你想要的位置</li><li>进入 <code>bin/</code> 目录： <ul><li>Mac / Linux：双击 <code>jmeter.sh</code>，或者终端执行 <code>./bin/jmeter.sh</code></li><li>Windows：双击 <code>jmeter.bat</code></li></ul></li></ol><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>JMeter 依赖 Java，需要 <strong>Java 8 或更高版本</strong>。检查一下有没有装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>如果没装，macOS 下 <code>brew install openjdk</code>，其他系统去 <a href="https://adoptium.net" target="_blank" rel="noreferrer">adoptium.net</a> 下载。</p><h2 id="切换中文界面" tabindex="-1">切换中文界面 <a class="header-anchor" href="#切换中文界面" aria-label="Permalink to &quot;切换中文界面&quot;">​</a></h2><p>默认是英文。如果你习惯中文：</p><blockquote><p>菜单栏 → <strong>Options</strong> → <strong>Choose Language</strong> → <strong>中文简体 ( Simplified Chinese )</strong></p></blockquote><p>本教程后续操作路径以中文界面为准。</p><h2 id="打开后你看到什么" tabindex="-1">打开后你看到什么 <a class="header-anchor" href="#打开后你看到什么" aria-label="Permalink to &quot;打开后你看到什么&quot;">​</a></h2><p>首次打开 JMeter，界面分三个区域：</p><ul><li><strong>顶部</strong> — 菜单栏和工具栏（新建、打开、保存、启动、停止等按钮）</li><li><strong>中间</strong> — 左右两栏布局： <ul><li>左侧 <strong>测试计划树</strong>，搭建脚本的地方。所有元件以树形显示，右键可添加。默认只有一个根节点 <strong>Test Plan</strong>（就是第一章说的根节点）。</li><li>右侧 <strong>属性编辑区</strong>，选中树上某个元件后，这里显示它的配置项。比如默认选中 Test Plan 时，显示名称和注释输入框。</li></ul></li><li><strong>底部</strong> — 状态栏，显示运行状态、错误数、警告数。</li></ul><h2 id="第一个操作-改个名字" tabindex="-1">第一个操作：改个名字 <a class="header-anchor" href="#第一个操作-改个名字" aria-label="Permalink to &quot;第一个操作：改个名字&quot;">​</a></h2><p>单击左侧树上的 <strong>Test Plan</strong>，右侧属性区会显示名称和注释。把名称改成你项目的名字，比如&quot;晋升平台压测&quot;。</p><blockquote><p>养成好习惯：每个项目开一个新的 Test Plan 名称，方便识别。</p></blockquote><h2 id="工具栏几个常用按钮" tabindex="-1">工具栏几个常用按钮 <a class="header-anchor" href="#工具栏几个常用按钮" aria-label="Permalink to &quot;工具栏几个常用按钮&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th style="text-align:center;">图标</th><th>作用</th></tr></thead><tbody><tr><td>新建 (New)</td><td style="text-align:center;">📄</td><td>新建一个测试计划</td></tr><tr><td>打开 (Open)</td><td style="text-align:center;">📂</td><td>打开已有的 .jmx 文件</td></tr><tr><td>保存 (Save)</td><td style="text-align:center;">💾</td><td>保存当前测试计划</td></tr><tr><td>启动 (Start)</td><td style="text-align:center;">▶</td><td>开始压测</td></tr><tr><td>停止 (Stop)</td><td style="text-align:center;">⏹</td><td>停止压测</td></tr><tr><td>清除 (Clear)</td><td style="text-align:center;">🧹</td><td>清除上一次跑的结果数据</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一章完成了三件事：</p><ul><li><strong>安装</strong>：brew 一行命令，或者下载解压。前提是有 Java 8+。</li><li><strong>认识界面</strong>：顶部菜单+工具栏，左侧测试计划树，右侧属性编辑区，底部状态栏。</li><li><strong>第一个操作</strong>：给 Test Plan 改个名字。</li></ul><p>工具就绪，下一章开始搭第一个压测脚本。</p>',31)])])}const b=e(r,[["render",l]]);export{g as __pageData,b as default};
